    ('COMMUNICATION', 'Communication', 'Notifications, conversations, polls, PTM'),
    ('HEALTH', 'Health', 'Medical profiles, infirmary, medication'),
    ('ADMISSIONS', 'Admissions', 'Enquiries, applications, assessments, seat plans'),
    ('TRANSPORT', 'Transport', 'Routes, trips, boarding, live tracking (phase 2)'),
