JOIN permission p ON p.permission_code = v.permission_code
ON CONFLICT ON CONSTRAINT uq_staff_type_permission DO NOTHING;

-- Default role -> feature: a role sees a module's feature (and its sub-features) when it holds any
-- permission in that module; universal features go to every branch role.
INSERT INTO staff_type_feature (school_id, staff_type_id, feature_id)
SELECT DISTINCT NULL::BIGINT, m.staff_type_id, f.feature_id
FROM staff_type_permission m
JOIN permission p ON p.permission_id = m.permission_id
JOIN feature pf ON pf.feature_id = p.feature_id
JOIN (VALUES
    ('ATTENDANCE', 'ATTENDANCE'),
    ('STAFF_PRESENCE', 'STAFF_PRESENCE'),
    ('ACADEMICS', 'ACADEMICS'),
    ('FEE_MANAGEMENT', 'FEE_MANAGEMENT'),
    ('HOSTEL', 'HOSTEL'),
    ('CUSTODY', 'CUSTODY'),
    ('GATE', 'GATE'),
    ('INVENTORY', 'INVENTORY'),
    ('EXPENSES', 'EXPENSES'),
    ('HR_PAYROLL', 'HR_PAYROLL'),
    ('COMMUNICATION', 'COMMUNICATION'),
    ('HEALTH', 'HEALTH'),
    ('ADMISSIONS', 'ADMISSIONS'),
    ('TRANSPORT', 'TRANSPORT'),
    ('LIBRARY', 'LIBRARY'),
    ('MESS', 'MESS'),
    ('SECURITY', 'SECURITY'),
    ('RECORDS', 'RECORDS'),
    ('REPORTS', 'REPORTS'),
    ('BULK_IMPORT', 'BULK_IMPORT'),
    ('CONSENT', 'CONSENT'),
    ('DEDICATED_APP', 'DEDICATED_APP'),
    ('ASSISTANT_MCP', 'ASSISTANT_MCP'),
    ('ACADEMICS', 'EXAMS'),
    ('ACADEMICS', 'TIMETABLE'),
    ('ACADEMICS', 'HOMEWORK'),
    ('ACADEMICS', 'LESSON_PLANS'),
    ('ACADEMICS', 'ONLINE_QUIZ'),
    ('ACADEMICS', 'REPORT_CARDS'),
    ('ACADEMICS', 'COURSE_REGISTRATION'),
    ('ACADEMICS', 'BATCH_MANAGEMENT'),
    ('ACADEMICS', 'PLACEMENTS'),
    ('RECORDS', 'ALUMNI'),
    ('HOSTEL', 'DISCIPLINE'),
    ('INVENTORY', 'FACILITY'),
    ('FEE_MANAGEMENT', 'STORE_WALLET'),
    ('COMMUNICATION', 'NEWS_FEED'),
    ('COMMUNICATION', 'CALENDAR'),
    ('COMMUNICATION', 'PTM')
) AS g(module_code, feature_code) ON g.module_code = pf.feature_code
JOIN feature f ON f.feature_code = g.feature_code
WHERE m.school_id IS NULL
ON CONFLICT ON CONSTRAINT uq_staff_type_feature DO NOTHING;

INSERT INTO staff_type_feature (school_id, staff_type_id, feature_id)
SELECT NULL, st.staff_type_id, f.feature_id
FROM staff_type st
JOIN feature f ON f.feature_code IN ('COMMUNICATION', 'NEWS_FEED', 'CALENDAR', 'CONSENT', 'ASSISTANT_MCP')
WHERE st.school_id IS NULL AND st.type_code <> 'SUPER_USER'
ON CONFLICT ON CONSTRAINT uq_staff_type_feature DO NOTHING;
INSERT INTO staff_type_feature (school_id, staff_type_id, feature_id)
SELECT NULL, st.staff_type_id, f.feature_id
FROM staff_type st
JOIN feature f ON f.feature_code IN ('REPORTS', 'BULK_IMPORT')
WHERE st.school_id IS NULL AND st.type_code IN ('SCHOOL_ADMIN', 'SYS_ADMIN', 'ADMIN', 'PRINCIPAL', 'ACCOUNTANT', 'HR_MANAGER')
ON CONFLICT ON CONSTRAINT uq_staff_type_feature DO NOTHING;

