-- CONSENT is always on: entitle and enable it for existing organizations and branches
INSERT INTO organization_feature (organization_id, feature_id)
SELECT o.organization_id, f.feature_id FROM organization o JOIN feature f ON f.feature_code = 'CONSENT'
ON CONFLICT DO NOTHING;
INSERT INTO school_feature (school_id, feature_id)
SELECT s.school_id, f.feature_id FROM school s JOIN feature f ON f.feature_code = 'CONSENT'
ON CONFLICT DO NOTHING;
